    clinicalNotes: 'Szczepienie zalecane wszystkim dzieciom od ukończenia 6. m.ż. Dzieciom poniżej 9. roku życia szczepionym po raz pierwszy w życiu podaje się 2 dawki w odstępie co najmniej 4 tygodni. W sezonie 2026/2027 w Polsce wg NIZP PZH (02.10.2026 r.) dostępne są wyłącznie trójwalentne szczepionki wstrzykiwane: Influvac i Vaxigrip (dla dzieci od 6. m.ż., bezpłatne <18 r.ż. na wykazie 84W D1 z kodem „DZ” lub 50% w A1 = 26,65 zł) oraz wysokodawkowa Efluelda (wyłącznie >=60 lat, wyłączona z wyboru pediatrycznego). Szczepionka donosowa Fluenz jest w sezonie 2026/2027 niedostępna w Polsce (decyzja KE z 14.07.2025 r. wycofująca Fluenz Tetra; brak na wykazie 84W).',
