      productType: 'W sezonie 2026/2027 wg NIZP PZH (02.10.2026) wyłącznie preparaty trójwalentne wstrzykiwane: (1) Influvac (trójwalentna podjednostkowa, od 6. m.ż., GTIN 05901797711283, 84W D1+A1+E); (2) Vaxigrip (trójwalentna split, od 6. m.ż., GTIN 05909991561505, 84W D1+A1+E); (3) Efluelda (>=60 lat, wyłączona). Donosowy Fluenz: niedostępny w 2026/2027 (wycofanie pozwolenia Fluenz Tetra KE 14.07.2025 r.). UWAGA: Historyczna karta vac-vaxigrip-tetra (4-walentna VaxigripTetra) w katalogu NIE stanowi aktualnej dokumentacji ChPL trójwalentnego Vaxigrip 2026/2027.',
      conditions: 'Bezpłatność apteczna z kodem „DZ” (lista D1) przysługuje do dnia poprzedzającego 18. urodziny WYŁĄCZNIE dla dostępnych trójwalentnych Vaxigrip i Influvac (od 18. urodzin prawo do DZ wygasa i na A1 obowiązuje 50% = 26,65 zł). Preparat donosowy Fluenz jest wyłączony z wyboru pediatrycznego jako niedostępny w Polsce w sezonie 2026/2027 (PZH 02.10.2026; brak na 84W; wycofanie Fluenz Tetra KE 14.07.2025). Dla kobiet w ciąży i połogu utrzymano otwartą kontrolę rozbieżności dot. warunków stosowania wykazu E / kodu „C” (art. 43b ust. 1–4 Dz.U. 2025 poz. 1461 vs PZH 02.10.2026). Szczepienie dzieci <18 lat realizuje POZ NFZ; apteki NFZ wyłącznie >=18 r.ż.',
      validityPeriod: 'Sezon 2026/2027: Obwieszczenie refundacyjne MZ nr 84W od 01.10.2026 r. (decyzje A1 Influvac/Vaxigrip od 01.07.2026 r. na 2 lata) + komunikat NIZP PZH z 02.10.2026 r.',
