    clinicalNotes: 'Szczepienie rozpoczęte od ukończenia 14. r.ż. realizuje się w schemacie 3-dawkowym (Cervarix: 0, 1, 6 mies.; Gardasil 9: 0, 2, 6 mies.; wyjątek: 2. dawka po rozpoczęciu przed 14. r.ż. kończona bezpłatnie jako 2-dawkowa). GRANICA 18. URODZIN ZMIENIA ODPŁATNOŚĆ: (1) Przed ukończeniem 18. r.ż.: Cervarix w aptece 0 zł na D1 z kodem „DZ” (bez DZ 50% w A1 = 139,44 zł), Gardasil 9 poza 84W (100% odpłatny); (2) Od dnia 18. urodzin prawo do „DZ” wygasa — Cervarix aptecznie ma 50% na A1 (139,44 zł), a dla osób >=18 lat i <26 lat obowiązuje czasowy program MZ/GIS z 02.10.2026 r. wył. dla Cervarix (51 000 dawek, start przed 25. urodzinami, wszystkie 3 dawki 0, 1, 6 mies. podane do 31.05.2027 r.; lokalnie w obszarze WSSE we Wrocławiu pula wyczerpana i zamknięta 05.11.2026 r.).',
